/**
 * Hero plate — the real park polygons this build serves, as drawable outlines.
 *
 * `public/data/hero-plate.json` is generated by `scripts/build-hero-plate.mjs`
 * from `public/data/Parks.geojson`. It is a plate, not a scatter: every park is
 * its own projected outline, so the picture cannot place a park somewhere its
 * boundary does not go. The earlier hero plotted ring centroids, which fall
 * outside their own polygon for L-shapes and always mis-state size.
 *
 * Everything here is defensive. The file is a build artifact, so a partial or
 * hand-edited file must yield no plate rather than invented shapes.
 */

export interface HeroPlateType {
  label: string;
  count: number;
  color: string;
}

export interface HeroPlatePark {
  name: string;
  /** Index into `types`. */
  typeIndex: number;
  /** Closed SVG path data in viewBox units, one entry per outer ring. */
  paths: string[];
}

export interface HeroPlate {
  generatedAt: string | null;
  viewBox: [number, number];
  /** Ground metres represented by one viewBox unit; null when not stated. */
  metresPerUnit: number | null;
  types: HeroPlateType[];
  parks: HeroPlatePark[];
}

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;
const HEX_COLOUR = /^#[0-9a-f]{6}$/i;
/** Absolute move, then line-to segments, then close. Nothing else is needed. */
const PATH_DATA = /^M-?\d+(?:\.\d+)? -?\d+(?:\.\d+)?(?:L-?\d+(?:\.\d+)? -?\d+(?:\.\d+)?)+Z$/;
const MAX_PATH_LENGTH = 4000;

function isFiniteNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}

/**
 * Parses the served plate. Returns null when the file is not usable at all;
 * individual bad parks are dropped rather than poisoning the drawing.
 */
export function parseHeroPlate(raw: unknown): HeroPlate | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const record = raw as Record<string, unknown>;

  const rawViewBox = record.viewBox;
  if (!Array.isArray(rawViewBox) || rawViewBox.length !== 2) return null;
  const [width, height] = rawViewBox;
  if (!isFiniteNumber(width) || !isFiniteNumber(height)) return null;
  if (width < 100 || width > 4000 || height < 100 || height > 4000) return null;

  const rawTypes = Array.isArray(record.types) ? record.types : [];
  const types: HeroPlateType[] = [];
  for (const entry of rawTypes) {
    if (!entry || typeof entry !== "object") continue;
    const type = entry as Record<string, unknown>;
    if (typeof type.label !== "string" || !type.label.trim()) continue;
    if (typeof type.color !== "string" || !HEX_COLOUR.test(type.color)) continue;
    types.push({
      label: type.label.trim(),
      count: isFiniteNumber(type.count) && type.count >= 0 ? Math.trunc(type.count) : 0,
      color: type.color,
    });
  }
  if (types.length === 0) return null;

  const rawParks = Array.isArray(record.parks) ? record.parks : [];
  const parks: HeroPlatePark[] = [];
  for (const entry of rawParks) {
    if (!entry || typeof entry !== "object") continue;
    const park = entry as Record<string, unknown>;
    if (!isFiniteNumber(park.typeIndex)) continue;
    const typeIndex = Math.trunc(park.typeIndex);
    if (typeIndex < 0 || typeIndex >= types.length) continue;
    if (!Array.isArray(park.paths)) continue;

    const paths = park.paths.filter(
      (value): value is string =>
        typeof value === "string" && value.length <= MAX_PATH_LENGTH && PATH_DATA.test(value),
    );
    if (paths.length === 0) continue;

    parks.push({
      name: typeof park.name === "string" ? park.name.trim() : "",
      typeIndex,
      paths,
    });
  }
  if (parks.length === 0) return null;

  const generatedAt =
    typeof record.generatedAt === "string" && ISO_DATE.test(record.generatedAt)
      ? record.generatedAt
      : null;

  const metresPerUnit =
    isFiniteNumber(record.metresPerUnit) && record.metresPerUnit > 0 && record.metresPerUnit < 1000
      ? record.metresPerUnit
      : null;

  return { generatedAt, viewBox: [width, height], metresPerUnit, types, parks };
}

/** Number of drawn outlines per type, in the order of `plate.types`. */
export function countPlateTypes(plate: Pick<HeroPlate, "parks" | "types">): number[] {
  const counts = plate.types.map(() => 0);
  for (const park of plate.parks) {
    if (park.typeIndex >= 0 && park.typeIndex < counts.length) counts[park.typeIndex] += 1;
  }
  return counts;
}

/** Parks of each type, ready to be drawn as one group per type. */
export function groupPlateParks(
  plate: Pick<HeroPlate, "parks" | "types">,
): { type: HeroPlateType; parks: HeroPlatePark[] }[] {
  return plate.types.map((type, index) => ({
    type,
    parks: plate.parks.filter((park) => park.typeIndex === index),
  }));
}

/** Caption copy for the resting plate — the count is already stated above it. */
export function describePlate(): string {
  return "Real park boundaries, drawn to scale";
}

const SCALE_CANDIDATES = [250, 500, 1000, 2000, 5000];

/**
 * The largest round distance whose bar stays under 30% of the plate's height,
 * so the bar is legible at every width without crossing the drawing.
 */
export function scaleBarMetres(plate: Pick<HeroPlate, "metresPerUnit" | "viewBox">): number | null {
  if (!plate.metresPerUnit) return null;
  const height = plate.viewBox[1];
  let chosen: number | null = null;
  for (const metres of SCALE_CANDIDATES) {
    if (metres / plate.metresPerUnit / height <= 0.3) chosen = metres;
  }
  return chosen;
}

/** Bar length as a percentage of the square plot's width. */
export function scaleBarPercent(
  plate: Pick<HeroPlate, "metresPerUnit" | "viewBox">,
  metres: number,
): number {
  if (!plate.metresPerUnit) return 0;
  // The plate is fitted by height into a square, so one viewBox unit is
  // (100 / viewBoxHeight)% of the plot's width.
  return ((metres / plate.metresPerUnit) / plate.viewBox[1]) * 100;
}
